import React, {useEffect, useMemo, useRef, useState} from "react";
import {
    Alert,
    Button,
    Chip,
    CircularProgress,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    InputAdornment,
    LinearProgress,
    MenuItem,
    TextField,
    Tooltip,
} from "@mui/material";
import AddOutlinedIcon from "@mui/icons-material/AddOutlined";
import ArrowBackOutlinedIcon from "@mui/icons-material/ArrowBackOutlined";
import CheckCircleOutlineOutlinedIcon from "@mui/icons-material/CheckCircleOutlineOutlined";
import DeleteOutlineOutlinedIcon from "@mui/icons-material/DeleteOutlineOutlined";
import DownloadOutlinedIcon from "@mui/icons-material/DownloadOutlined";
import EditNoteOutlinedIcon from "@mui/icons-material/EditNoteOutlined";
import LocalShippingOutlinedIcon from "@mui/icons-material/LocalShippingOutlined";
import SaveOutlinedIcon from "@mui/icons-material/SaveOutlined";
import SearchOutlinedIcon from "@mui/icons-material/SearchOutlined";
import SendOutlinedIcon from "@mui/icons-material/SendOutlined";
import VisibilityOutlinedIcon from "@mui/icons-material/VisibilityOutlined";
import {toast} from "react-toastify";
import {useNavigate, useParams} from "react-router-dom";
import {useAuth} from "../../auth/AuthContext";
import {getApiErrorMessage} from "../../api/errors";
import {
    CommercialOffer,
    CommercialOfferEditLine,
    CommercialOfferProduct,
    formatOfferDate,
    formatOfferMoney,
    normalizeOfferStatus,
    offerStatusColors,
    offerStatusLabels,
} from "../../models/commercialOffer";
import {
    EmptyState,
    FieldGrid,
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    Surface,
} from "../../ui/commonStyled/commonStyled";
import {
    useApproveCommercialOfferMutation,
    useConvertCommercialOfferMutation,
    useCreateCommercialOfferMutation,
    useDownloadCommercialOfferPdfMutation,
    useGetCommercialOfferCustomersQuery,
    useGetCommercialOfferProductsQuery,
    useGetCommercialOfferQuery,
    useGetCommercialOfferTemplatesQuery,
    useIssueCommercialOfferMutation,
    useReviseCommercialOfferMutation,
    useSendCommercialOfferMutation,
    useUpdateCommercialOfferCustomerMutation,
    useUpdateCommercialOfferMutation,
    usePreviewCommercialOfferPdfMutation,
} from "./commercialOffersApi";
import {
    ActionStack,
    EditorColumn,
    EditorGrid,
    LineList,
    LineRow,
    MobileHidden,
    ProductInfo,
    ProductList,
    ProductMeta,
    ProductName,
    ProductRow,
    SectionHeading,
    SectionTitle,
    StatusLine,
    Timeline,
    TimelineItem,
    TotalRow,
} from "./commercialOfferStyles";

const dateInputValue = (value?: string) => value ? value.slice(0, 10) : "";

const normalizePacks = (product: CommercialOfferProduct) => {
    const minimum = Math.max(1, product.minimumPacks || 1);
    const multiple = Math.max(1, product.packMultiple || 1);
    return Math.ceil(minimum / multiple) * multiple;
};

const CommercialOfferEditorPage = () => {
    const {id} = useParams();
    const isNew = !id || id === "new";
    const navigate = useNavigate();
    const {isCompanyAdmin} = useAuth();
    const {data: customers = [], isLoading: customersLoading, refetch: refetchCustomers} = useGetCommercialOfferCustomersQuery();
    const {data: templates = [], isLoading: templatesLoading} = useGetCommercialOfferTemplatesQuery();
    const {
        data: offer,
        isLoading: offerLoading,
        isError: offerError,
        refetch: refetchOffer,
    } = useGetCommercialOfferQuery(id ?? "", {skip: isNew});

    const [selectedCustomerId, setSelectedCustomerId] = useState<number | "">("");
    const [customerEmail, setCustomerEmail] = useState("");
    const [customerTaxNumber, setCustomerTaxNumber] = useState("");
    const [customerContract, setCustomerContract] = useState("");
    const [validUntil, setValidUntil] = useState("");
    const [templateId, setTemplateId] = useState("");
    const [notes, setNotes] = useState("");
    const [lines, setLines] = useState<CommercialOfferEditLine[]>([]);
    const [productSearch, setProductSearch] = useState("");
    const [approvalOpen, setApprovalOpen] = useState(false);
    const [approvalReason, setApprovalReason] = useState("Согласовано");
    const [previewUrl, setPreviewUrl] = useState("");
    const initializedStamp = useRef("");

    const [createOffer, {isLoading: creating}] = useCreateCommercialOfferMutation();
    const [updateCustomer, {isLoading: updatingCustomer}] = useUpdateCommercialOfferCustomerMutation();
    const [updateOffer, {isLoading: saving}] = useUpdateCommercialOfferMutation();
    const [issueOffer, {isLoading: issuing}] = useIssueCommercialOfferMutation();
    const [approveOffer, {isLoading: approving}] = useApproveCommercialOfferMutation();
    const [reviseOffer, {isLoading: revising}] = useReviseCommercialOfferMutation();
    const [sendOffer, {isLoading: sending}] = useSendCommercialOfferMutation();
    const [convertOffer, {isLoading: converting}] = useConvertCommercialOfferMutation();
    const [downloadPdf, {isLoading: downloading}] = useDownloadCommercialOfferPdfMutation();
    const [previewPdf, {isLoading: previewing}] = usePreviewCommercialOfferPdfMutation();

    const customerId = isNew ? Number(selectedCustomerId) : offer?.customerId ?? 0;
    const customer = customers.find((item) => item.id === customerId);
    const {
        data: products = [],
        isLoading: productsLoading,
        isError: productsError,
    } = useGetCommercialOfferProductsQuery(
        {customerId, includeUnavailable: true},
        {skip: isNew || !customerId},
    );

    useEffect(() => {
        if (!offer || initializedStamp.current === offer.concurrencyStamp) {
            return;
        }

        initializedStamp.current = offer.concurrencyStamp;
        setValidUntil(dateInputValue(offer.validUntil));
        setTemplateId(offer.templateId || "");
        setNotes(offer.notes || "");
        setLines(offer.lines.map((line) => ({
            productId: line.productId,
            packs: line.packs,
            manualPrice: /руч|manual/i.test(line.priceSource) ? line.unitPrice : null,
        })));
    }, [offer]);

    useEffect(() => {
        if (!templateId && templates.length > 0 && (isNew || !offer?.templateId)) {
            setTemplateId(templates[0].id);
        }
    }, [isNew, offer?.templateId, templateId, templates]);

    useEffect(() => () => {
        if (previewUrl) {
            URL.revokeObjectURL(previewUrl);
        }
    }, [previewUrl]);

    useEffect(() => {
        if (!offer?.deliveryPending) {
            return;
        }

        const interval = window.setInterval(() => void refetchOffer(), 2500);
        return () => window.clearInterval(interval);
    }, [offer?.deliveryPending, refetchOffer]);

    const selectedCustomer = customers.find((item) => item.id === Number(selectedCustomerId));

    const selectCustomer = (value: number) => {
        setSelectedCustomerId(value);
        const selected = customers.find((item) => item.id === value);
        setCustomerEmail(selected?.email ?? "");
        setCustomerTaxNumber(selected?.taxNumber ?? "");
        setCustomerContract(selected?.contract ?? "");
    };

    const filteredProducts = useMemo(() => {
        const query = productSearch.trim().toLocaleLowerCase("ru-RU");
        return products.filter((product) => !query || [product.name, product.sku, product.gtin, product.group]
            .some((value) => value?.toLocaleLowerCase("ru-RU").includes(query)));
    }, [productSearch, products]);

    const productById = useMemo(() => new Map(products.map((product) => [product.id, product])), [products]);
    const offerLineById = useMemo(
        () => new Map((offer?.lines ?? []).map((line) => [line.productId, line])),
        [offer?.lines],
    );

    const editableStatus = offer ? normalizeOfferStatus(offer.status) : "draft";
    const isDraft = editableStatus === "draft";
    const busy = saving || issuing || approving || revising || sending || converting || downloading || previewing;

    const total = useMemo(() => lines.reduce((sum, line) => {
        const product = productById.get(line.productId);
        const savedLine = offerLineById.get(line.productId);
        const packSize = product?.packSize ?? savedLine?.packSize ?? 1;
        const unitPrice = line.manualPrice ?? product?.unitPrice ?? savedLine?.unitPrice ?? 0;
        return sum + line.packs * packSize * unitPrice;
    }, 0), [lines, offerLineById, productById]);

    const runAction = async (action: () => Promise<unknown>, successMessage: string) => {
        try {
            await action();
            toast.success(successMessage);
            if (!isNew) {
                await refetchOffer();
            }
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось выполнить действие."));
            throw error;
        }
    };

    const saveCustomerProfile = async () => {
        if (!selectedCustomerId) {
            return;
        }

        try {
            await updateCustomer({
                customerId: Number(selectedCustomerId),
                email: customerEmail.trim(),
                taxNumber: customerTaxNumber.trim(),
                contract: customerContract.trim(),
            }).unwrap();
            toast.success("Коммерческий профиль клиента сохранён.");
            await refetchCustomers();
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось сохранить профиль клиента."));
        }
    };

    const createDraft = async () => {
        if (!selectedCustomerId) {
            toast.warning("Выберите клиента.");
            return;
        }
        if (!templateId) {
            toast.warning("Выберите или создайте шаблон КП.");
            return;
        }

        try {
            const profileChanged = Boolean(selectedCustomer) && (
                customerEmail.trim() !== selectedCustomer?.email ||
                customerTaxNumber.trim() !== selectedCustomer?.taxNumber ||
                customerContract.trim() !== selectedCustomer?.contract
            );
            if (profileChanged) {
                await updateCustomer({
                    customerId: Number(selectedCustomerId),
                    email: customerEmail.trim(),
                    taxNumber: customerTaxNumber.trim(),
                    contract: customerContract.trim(),
                }).unwrap();
            }
            const created = await createOffer({customerId: Number(selectedCustomerId), templateId}).unwrap();
            toast.success(`Черновик ${created.number} создан.`);
            navigate(`/commercialOffers/${created.id}`, {replace: true});
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось создать коммерческое предложение."));
        }
    };

    const buildEditRequest = (currentOffer: CommercialOffer) => ({
        concurrencyStamp: currentOffer.concurrencyStamp,
        validUntil: new Date(`${validUntil}T23:59:59`).toISOString(),
        templateId: templateId || null,
        notes: notes.trim(),
        lines: lines.map((line) => ({
            productId: line.productId,
            packs: Number(line.packs),
            manualPrice: line.manualPrice === null || line.manualPrice === undefined
                ? null
                : Number(line.manualPrice),
        })),
    });

    const saveDraft = async (showSuccess = true) => {
        if (!offer || !id) {
            throw new Error("Коммерческое предложение не загружено.");
        }
        if (!validUntil) {
            throw new Error("Укажите срок действия предложения.");
        }

        const updated = await updateOffer({id, body: buildEditRequest(offer)}).unwrap();
        initializedStamp.current = updated.concurrencyStamp;
        if (showSuccess) {
            toast.success("Черновик сохранён.");
        }
        return updated;
    };

    const handleSave = async () => {
        try {
            await saveDraft();
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось сохранить КП."));
        }
    };

    const handleIssue = async () => {
        if (!lines.length) {
            toast.warning("Добавьте хотя бы один товар.");
            return;
        }
        if (!customer?.email) {
            toast.warning("Заполните e-mail клиента перед выпуском КП.");
            return;
        }

        try {
            const updated = await saveDraft(false);
            await issueOffer({id: updated.id, concurrencyStamp: updated.concurrencyStamp}).unwrap();
            toast.success("Новая версия КП выпущена. PDF готов к скачиванию.");
            await refetchOffer();
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось выпустить версию КП."));
        }
    };

    const handleApprove = async () => {
        if (!offer || !id || !approvalReason.trim()) {
            return;
        }

        try {
            await approveOffer({id, concurrencyStamp: offer.concurrencyStamp, reason: approvalReason.trim()}).unwrap();
            setApprovalOpen(false);
            toast.success("КП согласовано.");
            await refetchOffer();
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось согласовать КП."));
        }
    };

    const handlePdf = async () => {
        if (!offer || !id || !offer.revisionNumber) {
            return;
        }

        try {
            const blob = await downloadPdf({id, version: offer.revisionNumber}).unwrap();
            const url = URL.createObjectURL(blob);
            const link = document.createElement("a");
            link.href = url;
            link.download = `${offer.number || "commercial-offer"}-v${offer.revisionNumber}.pdf`.replace(/[\\/:*?"<>|]+/g, "-");
            document.body.appendChild(link);
            link.click();
            link.remove();
            URL.revokeObjectURL(url);
            toast.success("PDF сохранён в загрузки.");
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось скачать PDF."));
        }
    };

    const handlePreview = async () => {
        if (!offer || !id) {
            return;
        }

        try {
            if (isDraft) {
                await saveDraft(false);
            }
            const blob = await previewPdf({id}).unwrap();
            if (previewUrl) {
                URL.revokeObjectURL(previewUrl);
            }
            setPreviewUrl(URL.createObjectURL(blob));
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось сформировать предпросмотр."));
        }
    };

    const addProduct = (product: CommercialOfferProduct) => {
        if (lines.some((line) => line.productId === product.id)) {
            return;
        }
        setLines((current) => [...current, {
            productId: product.id,
            packs: normalizePacks(product),
            manualPrice: null,
        }]);
    };

    const updateLine = (productId: number, patch: Partial<CommercialOfferEditLine>) => {
        setLines((current) => current.map((line) => line.productId === productId ? {...line, ...patch} : line));
    };

    if (isNew) {
        return (
            <MainDiv>
                <PageHeader>
                    <PageTitleGroup>
                        <Button startIcon={<ArrowBackOutlinedIcon/>} onClick={() => navigate("/commercialOffers", {replace: true})} sx={{alignSelf: "start", px: 0}}>
                            К списку КП
                        </Button>
                        <PageTitle>Новое коммерческое предложение</PageTitle>
                        <PageSubtitle>Выберите клиента и шаблон. После создания откроется редактор товаров и цен.</PageSubtitle>
                    </PageTitleGroup>
                </PageHeader>

                <Surface style={{maxWidth: 820}}>
                    {customersLoading && <LinearProgress sx={{mb: 2}}/>}
                    <FieldGrid>
                        <TextField
                            select
                            fullWidth
                            label="Клиент"
                            value={selectedCustomerId}
                            onChange={(event) => selectCustomer(Number(event.target.value))}
                        >
                            {customers.map((item) => (
                                <MenuItem key={item.id} value={item.id} disabled={item.isBlocked}>
                                    {item.name}{item.isBlocked ? " — заблокирован" : ""}
                                </MenuItem>
                            ))}
                        </TextField>
                        <TextField label="Контакт" value={selectedCustomer?.contact ?? ""} disabled/>
                        <TextField
                            label="E-mail для отправки КП"
                            type="email"
                            value={customerEmail}
                            onChange={(event) => setCustomerEmail(event.target.value)}
                        />
                        <TextField
                            label="УНП / налоговый номер"
                            value={customerTaxNumber}
                            onChange={(event) => setCustomerTaxNumber(event.target.value)}
                        />
                        <TextField
                            label="Договор"
                            value={customerContract}
                            onChange={(event) => setCustomerContract(event.target.value)}
                        />
                        <TextField
                            select
                            fullWidth
                            label="Шаблон КП"
                            value={templateId}
                            disabled={templatesLoading || templates.length === 0}
                            onChange={(event) => setTemplateId(event.target.value)}
                        >
                            {templates.map((item) => (
                                <MenuItem key={item.id} value={item.id}>{item.name}</MenuItem>
                            ))}
                        </TextField>
                    </FieldGrid>

                    {!templatesLoading && templates.length === 0 && (
                        <Alert severity="info" sx={{mt: 2}} action={<Button onClick={() => navigate("/commercialOffers/templates/new")}>Создать шаблон</Button>}>
                            Для формирования PDF сначала создайте шаблон компании.
                        </Alert>
                    )}

                    {selectedCustomerId && !customerEmail.trim() && (
                        <Alert severity="warning" sx={{mt: 2}}>
                            Без e-mail черновик создать можно, но выпустить и отправить КП не получится.
                        </Alert>
                    )}

                    <div style={{display: "flex", gap: 10, flexWrap: "wrap", marginTop: 18}}>
                        <Button
                            variant="outlined"
                            onClick={() => void saveCustomerProfile()}
                            disabled={!selectedCustomerId || updatingCustomer}
                        >
                            {updatingCustomer ? "Сохранение…" : "Сохранить реквизиты"}
                        </Button>
                        <Button
                            variant="contained"
                            size="large"
                            startIcon={creating ? <CircularProgress size={18}/> : <AddOutlinedIcon/>}
                            onClick={() => void createDraft()}
                            disabled={!selectedCustomerId || !templateId || creating || selectedCustomer?.isBlocked}
                        >
                            Создать черновик КП
                        </Button>
                    </div>
                </Surface>
            </MainDiv>
        );
    }

    if (offerLoading) {
        return <MainDiv><LinearProgress/><EmptyState>Загрузка коммерческого предложения…</EmptyState></MainDiv>;
    }

    if (offerError || !offer) {
        return (
            <MainDiv>
                <Alert severity="error" action={<Button onClick={() => void refetchOffer()}>Повторить</Button>}>
                    Не удалось загрузить коммерческое предложение.
                </Alert>
            </MainDiv>
        );
    }

    const canRevise = ["pendingApproval", "ready", "sent", "viewed", "expired"].includes(editableStatus);
    const canConvert = ["ready", "sent", "viewed", "accepted"].includes(editableStatus);

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <Button startIcon={<ArrowBackOutlinedIcon/>} onClick={() => navigate("/commercialOffers", {replace: true})} sx={{alignSelf: "start", px: 0}}>
                        К списку КП
                    </Button>
                    <PageTitle>{offer.number}</PageTitle>
                    <PageSubtitle>{offer.customerName} · менеджер {offer.manager || "не указан"}</PageSubtitle>
                </PageTitleGroup>
                <Chip color={offerStatusColors[editableStatus]} label={offerStatusLabels[editableStatus]}/>
            </PageHeader>

            {busy && <LinearProgress sx={{mb: 2}}/>}
            {offer.deliveryPending && <Alert severity="info" sx={{mb: 2}}>Письмо поставлено в очередь и отправляется клиенту.</Alert>}
            {offer.needsApproval && <Alert severity="warning" sx={{mb: 2}}>Цена одной или нескольких позиций ниже минимальной. Требуется согласование администратора.</Alert>}

            <EditorGrid>
                <EditorColumn>
                    {isDraft && (
                        <Surface>
                            <SectionHeading>
                                <div>
                                    <SectionTitle>Каталог товаров</SectionTitle>
                                    <ProductMeta>Цены и остатки рассчитаны для выбранного клиента.</ProductMeta>
                                </div>
                                <TextField
                                    size="small"
                                    placeholder="Найти товар"
                                    value={productSearch}
                                    onChange={(event) => setProductSearch(event.target.value)}
                                    InputProps={{
                                        startAdornment: <InputAdornment position="start"><SearchOutlinedIcon fontSize="small"/></InputAdornment>,
                                    }}
                                />
                            </SectionHeading>
                            {productsLoading && <LinearProgress/>}
                            {productsError && <Alert severity="error">Не удалось загрузить каталог товаров.</Alert>}
                            <ProductList>
                                {filteredProducts.map((product) => {
                                    const added = lines.some((line) => line.productId === product.id);
                                    return (
                                        <ProductRow key={product.id} $disabled={!product.eligible}>
                                            <ProductInfo>
                                                <ProductName>{product.name}</ProductName>
                                                <ProductMeta>Арт. {product.sku || "—"} · упаковка {product.packSize} шт.</ProductMeta>
                                            </ProductInfo>
                                            <MobileHidden>
                                                <ProductName>{product.availablePacks} уп.</ProductName>
                                                <ProductMeta>доступно</ProductMeta>
                                            </MobileHidden>
                                            <MobileHidden>
                                                <ProductName>{formatOfferMoney(product.unitPrice, customer?.currency)}</ProductName>
                                                {product.discountPercent > 0 && <ProductMeta>скидка {product.discountPercent}%</ProductMeta>}
                                            </MobileHidden>
                                            <Button
                                                size="small"
                                                variant={added ? "outlined" : "contained"}
                                                startIcon={!added ? <AddOutlinedIcon/> : undefined}
                                                disabled={added || !product.eligible}
                                                onClick={() => addProduct(product)}
                                            >
                                                {added ? "Добавлен" : "Добавить"}
                                            </Button>
                                        </ProductRow>
                                    );
                                })}
                            </ProductList>
                        </Surface>
                    )}

                    <Surface>
                        <SectionHeading>
                            <div>
                                <SectionTitle>Состав предложения</SectionTitle>
                                <ProductMeta>{lines.length} позиций</ProductMeta>
                            </div>
                        </SectionHeading>

                        {!lines.length && (
                            <EmptyState>Добавьте товары из каталога, чтобы сформировать КП.</EmptyState>
                        )}

                        <LineList>
                            {lines.map((line) => {
                                const product = productById.get(line.productId);
                                const savedLine = offerLineById.get(line.productId);
                                const name = product?.name ?? savedLine?.name ?? `Товар #${line.productId}`;
                                const packSize = product?.packSize ?? savedLine?.packSize ?? 1;
                                const price = line.manualPrice ?? product?.unitPrice ?? savedLine?.unitPrice ?? 0;
                                const rowTotal = line.packs * packSize * price;
                                return (
                                    <LineRow key={line.productId}>
                                        <ProductInfo>
                                            <ProductName>{name}</ProductName>
                                            <ProductMeta>{product?.sku ?? savedLine?.sku ?? ""} · {packSize} шт. в упаковке</ProductMeta>
                                        </ProductInfo>
                                        <TextField
                                            size="small"
                                            type="number"
                                            label="Упаковки"
                                            value={line.packs}
                                            disabled={!isDraft}
                                            inputProps={{min: product?.minimumPacks ?? 1, step: product?.packMultiple ?? 1}}
                                            onChange={(event) => updateLine(line.productId, {packs: Math.max(1, Number(event.target.value))})}
                                        />
                                        <Tooltip title={isCompanyAdmin ? "Можно задать цену вручную" : "Ручная цена доступна администратору"}>
                                            <TextField
                                                size="small"
                                                type="number"
                                                label="Цена за шт."
                                                value={line.manualPrice ?? price}
                                                disabled={!isDraft || !isCompanyAdmin}
                                                inputProps={{min: 0, step: .01}}
                                                onChange={(event) => updateLine(line.productId, {manualPrice: Number(event.target.value)})}
                                            />
                                        </Tooltip>
                                        <MobileHidden>
                                            <ProductName>{formatOfferMoney(rowTotal, customer?.currency)}</ProductName>
                                            {price < (product?.minimumPrice ?? savedLine?.minimumPrice ?? 0) && <ProductMeta style={{color: "var(--color-danger)"}}>ниже минимума</ProductMeta>}
                                        </MobileHidden>
                                        <IconButton
                                            aria-label={`Удалить ${name}`}
                                            disabled={!isDraft}
                                            onClick={() => setLines((current) => current.filter((item) => item.productId !== line.productId))}
                                        >
                                            <DeleteOutlineOutlinedIcon/>
                                        </IconButton>
                                    </LineRow>
                                );
                            })}
                        </LineList>

                        <TotalRow>
                            <span>Итого</span>
                            <strong>{formatOfferMoney(isDraft ? total : offer.total, customer?.currency)}</strong>
                        </TotalRow>
                    </Surface>

                    {!!offer.events?.length && (
                        <Surface>
                            <SectionHeading><SectionTitle>История</SectionTitle></SectionHeading>
                            <Timeline>
                                {[...offer.events].reverse().map((event) => (
                                    <TimelineItem key={event.id}>
                                        <ProductName>{event.action}</ProductName>
                                        <ProductMeta>{formatOfferDate(event.at)} · {event.actor}</ProductMeta>
                                        {event.detail && <ProductMeta>{event.detail}</ProductMeta>}
                                    </TimelineItem>
                                ))}
                            </Timeline>
                        </Surface>
                    )}
                </EditorColumn>

                <EditorColumn>
                    <Surface>
                        <StatusLine>
                            <SectionTitle>Параметры КП</SectionTitle>
                            <Chip size="small" color={offerStatusColors[editableStatus]} label={offerStatusLabels[editableStatus]}/>
                        </StatusLine>
                        <ActionStack>
                            <TextField
                                fullWidth
                                type="date"
                                label="Действует до"
                                value={validUntil}
                                disabled={!isDraft}
                                InputLabelProps={{shrink: true}}
                                onChange={(event) => setValidUntil(event.target.value)}
                            />
                            <TextField
                                select
                                fullWidth
                                label="Шаблон PDF"
                                value={templateId}
                                disabled={!isDraft}
                                onChange={(event) => setTemplateId(event.target.value)}
                            >
                                {templates.map((item) => <MenuItem key={item.id} value={item.id}>{item.name}</MenuItem>)}
                            </TextField>
                            <Button variant="text" onClick={() => navigate("/commercialOffers/templates")}>
                                Открыть конструктор шаблонов
                            </Button>
                            <TextField
                                fullWidth
                                multiline
                                minRows={4}
                                label="Комментарий"
                                value={notes}
                                disabled={!isDraft}
                                onChange={(event) => setNotes(event.target.value)}
                            />
                        </ActionStack>
                    </Surface>

                    <Surface>
                        <SectionHeading><SectionTitle>Действия</SectionTitle></SectionHeading>
                        <ActionStack>
                            <Button fullWidth variant="outlined" startIcon={<VisibilityOutlinedIcon/>} onClick={() => void handlePreview()} disabled={busy || (isDraft && !templateId)}>
                                Предпросмотр сохранённого КП
                            </Button>
                            {isDraft && (
                                <>
                                    <Button fullWidth variant="outlined" startIcon={<SaveOutlinedIcon/>} onClick={() => void handleSave()} disabled={busy}>
                                        Сохранить черновик
                                    </Button>
                                    <Button fullWidth variant="contained" startIcon={<CheckCircleOutlineOutlinedIcon/>} onClick={() => void handleIssue()} disabled={busy || !lines.length}>
                                        Выпустить версию и PDF
                                    </Button>
                                </>
                            )}
                            {editableStatus === "pendingApproval" && isCompanyAdmin && (
                                <Button fullWidth color="success" variant="contained" startIcon={<CheckCircleOutlineOutlinedIcon/>} onClick={() => setApprovalOpen(true)} disabled={busy}>
                                    Согласовать цену
                                </Button>
                            )}
                            {editableStatus === "ready" && (
                                <Button fullWidth variant="contained" startIcon={<SendOutlinedIcon/>} onClick={() => void runAction(
                                    () => sendOffer({id: offer.id, concurrencyStamp: offer.concurrencyStamp}).unwrap(),
                                    "КП поставлено в очередь на отправку.",
                                ).catch(() => undefined)} disabled={busy || offer.deliveryPending}>
                                    Отправить клиенту
                                </Button>
                            )}
                            {offer.revisionNumber > 0 && (
                                <Button fullWidth variant="outlined" startIcon={<DownloadOutlinedIcon/>} onClick={() => void handlePdf()} disabled={busy}>
                                    Скачать PDF · версия {offer.revisionNumber}
                                </Button>
                            )}
                            {canRevise && (
                                <Button fullWidth variant="outlined" startIcon={<EditNoteOutlinedIcon/>} onClick={() => void runAction(
                                    () => reviseOffer({id: offer.id, concurrencyStamp: offer.concurrencyStamp}).unwrap(),
                                    "Создан новый черновик КП.",
                                ).catch(() => undefined)} disabled={busy || offer.deliveryPending}>
                                    Создать новую редакцию
                                </Button>
                            )}
                            {canConvert && (
                                <Button fullWidth color="success" variant="outlined" startIcon={<LocalShippingOutlinedIcon/>} onClick={async () => {
                                    try {
                                        const order = await convertOffer({id: offer.id, concurrencyStamp: offer.concurrencyStamp}).unwrap();
                                        toast.success(`Создан заказ ${order.number}.`);
                                        navigate(`/ordersManagement/${order.id}`);
                                    } catch (error) {
                                        toast.error(getApiErrorMessage(error, "Не удалось создать заказ."));
                                    }
                                }} disabled={busy}>
                                    Создать заказ из КП
                                </Button>
                            )}
                        </ActionStack>
                    </Surface>

                    <Surface>
                        <SectionHeading><SectionTitle>Клиент</SectionTitle></SectionHeading>
                        <ProductName>{offer.customerName}</ProductName>
                        <ProductMeta>{customer?.contact || "Контакт не указан"}</ProductMeta>
                        <ProductMeta>{customer?.email || "E-mail не указан"}</ProductMeta>
                        <ProductMeta>Договор: {customer?.contract || "—"}</ProductMeta>
                        <ProductMeta>Оплата: {customer?.paymentTerms || "—"}</ProductMeta>
                        <ProductMeta>Доставка: {customer?.deliveryTerms || "—"}</ProductMeta>
                    </Surface>
                </EditorColumn>
            </EditorGrid>

            <Dialog open={approvalOpen} onClose={() => setApprovalOpen(false)} fullWidth maxWidth="sm">
                <DialogTitle>Согласование коммерческого предложения</DialogTitle>
                <DialogContent>
                    <Alert severity="warning" sx={{mb: 2}}>
                        В КП есть цена ниже минимальной. Укажите причину согласования.
                    </Alert>
                    <TextField
                        autoFocus
                        fullWidth
                        multiline
                        minRows={3}
                        label="Причина"
                        value={approvalReason}
                        onChange={(event) => setApprovalReason(event.target.value)}
                    />
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setApprovalOpen(false)}>Отмена</Button>
                    <Button variant="contained" color="success" onClick={() => void handleApprove()} disabled={!approvalReason.trim() || approving}>
                        Согласовать
                    </Button>
                </DialogActions>
            </Dialog>
            <Dialog
                open={Boolean(previewUrl)}
                onClose={() => setPreviewUrl("")}
                fullWidth
                maxWidth="lg"
            >
                <DialogTitle>Предпросмотр {offer.number}</DialogTitle>
                <DialogContent dividers sx={{p: 0, height: "76vh"}}>
                    {previewUrl && (
                        <iframe
                            title={`Предпросмотр ${offer.number}`}
                            src={previewUrl}
                            style={{width: "100%", height: "100%", border: 0}}
                        />
                    )}
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setPreviewUrl("")}>Закрыть</Button>
                </DialogActions>
            </Dialog>
        </MainDiv>
    );
};

export default CommercialOfferEditorPage;
